<?php declare(strict_types=1); $title='Felhasználók – A Bata'; $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); require __DIR__.'/_layout_start.php'; ?>
<section class="admin-page"><p class="eyebrow">Adminisztráció</p><h1>Felhasználók</h1>
<?php if ($error !== null): ?><div class="alert" role="alert"><?= $e($error) ?></div><?php endif; ?><p><a class="button-link" href="/admin/users/create">+ Új felhasználó</a></p>
<div class="table-scroll" tabindex="0" role="region" aria-label="Admin felhasználók"><table><thead><tr><th>Név</th><th>E-mail-cím</th><th>Állapot</th><th>Létrehozva</th><th>Műveletek</th></tr></thead><tbody>
<?php foreach ($users as $user): ?><tr><td data-label="Név"><?= $e($user['name']) ?></td><td data-label="E-mail-cím"><?= $e($user['email']) ?></td><td data-label="Állapot"><?= $user['is_active'] ? 'Aktív' : 'Inaktív' ?></td><td data-label="Létrehozva"><?= $e($user['created_at']) ?></td><td class="table-actions"><form method="post" action="/admin/users/<?= (int)$user['id'] ?>/<?= $user['is_active'] ? 'deactivate' : 'activate' ?>"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><button class="compact <?= $user['is_active'] ? 'danger' : '' ?>" type="submit"><?= $user['is_active'] ? 'Inaktiválás' : 'Aktiválás' ?></button></form></td></tr><?php endforeach; ?>
<?php if ($users === []): ?><tr><td colspan="5">Nincs felhasználó.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/_layout_end.php'; ?>
